use crate::{GraphOperation, ImageError, RgbaImage};
use serde_json::Value;

/// Binary, full-resolution model masks generated by the same rasterizer as
/// every manual editing tool. Inference sees no opacity/blend modification;
/// the immutable source and final common compositor apply those exactly once.
pub struct InpaintMasks {
    pub width: u32,
    pub height: u32,
    pub target: Vec<u8>,
    pub protection: Vec<u8>,
}

fn validate(op: &GraphOperation) -> Result<(), ImageError> {
    crate::validation::operation(op)?;
    if op.kind != "repair.inpaint"
        || op.params.get("method").and_then(Value::as_str) != Some("lama")
    {
        return Err(ImageError::InvalidOperation(
            "model inpainting requires repair.inpaint method=lama".into(),
        ));
    }
    Ok(())
}

pub fn prepare_model_inpaint(
    source: &RgbaImage,
    op: &GraphOperation,
) -> Result<InpaintMasks, ImageError> {
    validate(op)?;
    let region = crate::mask::Region::read(op.params.get("region"));
    let n = source.width as usize * source.height as usize;
    let mut target = vec![0; n];
    let mut protection = vec![0; n];
    let enabled = op.enabled && crate::engine::number(&op.params, "opacity", 100.0) > 0.0;
    let protected_mask = op
        .params
        .get("protectMask")
        .map(crate::mask::PreparedMask::new);
    let selection = op.params.get("mask").map(crate::mask::PreparedMask::new);
    for y in 0..source.height {
        for x in 0..source.width {
            let i = y as usize * source.width as usize + x as usize;
            let nx = (x as f32 + 0.5) / source.width as f32;
            let ny = (y as f32 + 0.5) / source.height as f32;
            let frozen = protected_mask
                .as_ref()
                .map(|m| m.coverage(nx, ny, source.width, source.height) > 0.0)
                .unwrap_or(false);
            if frozen {
                protection[i] = 255;
            }
            let selected = selection
                .as_ref()
                .map(|m| m.coverage(nx, ny, source.width, source.height) > 0.0)
                .unwrap_or(true);
            if enabled
                && region.contains(nx, ny)
                && selected
                && !frozen
                && source.pixels[i * 4 + 3] > 0
            {
                target[i] = 255;
            }
        }
    }
    Ok(InpaintMasks {
        width: source.width,
        height: source.height,
        target,
        protection,
    })
}

pub fn composite_model_inpaint(
    source: &RgbaImage,
    candidate: &RgbaImage,
    op: &GraphOperation,
) -> Result<RgbaImage, ImageError> {
    let masks = prepare_model_inpaint(source, op)?;
    if source.width != candidate.width || source.height != candidate.height {
        return Err(ImageError::InvalidOperation(
            "model result dimensions must match the operation input".into(),
        ));
    }
    // Do not trust a model to retain alpha or restore unselected RGB. Narrow
    // its output before applying the shared mask, opacity and blend formula.
    let mut edit = source.clone();
    for (i, &selected) in masks.target.iter().enumerate() {
        if selected > 0 {
            edit.pixels[i * 4..i * 4 + 3].copy_from_slice(&candidate.pixels[i * 4..i * 4 + 3]);
        }
    }
    let mut result = crate::mask::composite(source, &edit, &op.params);
    for (i, &selected) in masks.target.iter().enumerate() {
        if selected == 0 {
            result.pixels[i * 4..i * 4 + 4].copy_from_slice(&source.pixels[i * 4..i * 4 + 4]);
        }
        result.pixels[i * 4 + 3] = source.pixels[i * 4 + 3];
    }
    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;
    fn op(params: Value) -> GraphOperation {
        serde_json::from_value(
            json!({"id":"model","type":"repair.inpaint","enabled":true,"params":params}),
        )
        .unwrap()
    }
    #[test]
    fn canonical_model_target_excludes_frozen_transparent_and_erased_pixels() {
        let source = RgbaImage::new(
            4,
            1,
            vec![
                100, 80, 60, 255, 100, 80, 60, 255, 7, 8, 9, 0, 100, 80, 60, 99,
            ],
        )
        .unwrap();
        let op = op(
            json!({"method":"lama","mask":{"shape":"raster","width":4,"height":1,"data":[255,255,255,0]},"protectMask":{"shape":"rect","region":{"x":0.25,"y":0,"width":0.25,"height":1}}}),
        );
        let masks = prepare_model_inpaint(&source, &op).unwrap();
        assert_eq!(masks.target, vec![255, 0, 0, 0]);
        assert_eq!(masks.protection, vec![0, 255, 0, 0]);
        let candidate = RgbaImage::new(4, 1, [220, 200, 180, 13].repeat(4)).unwrap();
        let result = composite_model_inpaint(&source, &candidate, &op).unwrap();
        assert_eq!(&result.pixels[..4], &[220, 200, 180, 255]);
        assert_eq!(&result.pixels[4..], &source.pixels[4..]);
    }
    #[test]
    fn model_compositing_uses_opacity_once_and_rejects_wrong_dimensions() {
        let source = RgbaImage::new(2, 1, [100, 80, 60, 79].repeat(2)).unwrap();
        let candidate = RgbaImage::new(2, 1, [200, 180, 160, 255].repeat(2)).unwrap();
        let mut op = op(json!({"method":"lama","opacity":50}));
        let result = composite_model_inpaint(&source, &candidate, &op).unwrap();
        assert_eq!(result.pixels, [150, 130, 110, 79].repeat(2));
        op.params["opacity"] = json!(0);
        assert_eq!(
            prepare_model_inpaint(&source, &op).unwrap().target,
            vec![0, 0]
        );
        assert_eq!(
            composite_model_inpaint(&source, &candidate, &op).unwrap(),
            source
        );
        let wrong = RgbaImage::new(1, 1, vec![1, 2, 3, 255]).unwrap();
        assert!(composite_model_inpaint(&source, &wrong, &op).is_err());
    }
    #[test]
    fn feathered_protection_is_frozen_even_with_multiply_blending() {
        let source = RgbaImage::new(2, 1, [100, 80, 60, 91].repeat(2)).unwrap();
        let candidate = RgbaImage::new(2, 1, [200, 180, 160, 255].repeat(2)).unwrap();
        let mut op = op(
            json!({"method":"lama","blendMode":"multiply","protectMask":{"shape":"raster","width":2,"height":1,"data":[128,0]}}),
        );
        let result = composite_model_inpaint(&source, &candidate, &op).unwrap();
        assert_eq!(&result.pixels[..4], &source.pixels[..4]);
        assert_ne!(&result.pixels[4..7], &source.pixels[4..7]);
        op.enabled = false;
        assert_eq!(
            composite_model_inpaint(&source, &candidate, &op).unwrap(),
            source
        );
    }
}
